const lockReaderCommentReplyStatuses = `-- name: LockReaderCommentReplyStatuses :many
SELECT status FROM reader_comments
WHERE root_id = $1::bigint OR parent_id = $1::bigint
ORDER BY id
FOR UPDATE
`

// The statuses of the rows that answer the comment or sit in the thread it roots, locked:
// whether deleting it would take approved replies with it (6.4). The lock makes a
// moderator's approval of one of them wait (or be waited on) instead of racing the
// delete's cascade; a reply inserted meanwhile waits on the comment's own row lock (its
// foreign key check).
func (q *Queries) LockReaderCommentReplyStatuses(ctx context.Context, id int64) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, lockReaderCommentReplyStatuses, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var status string
		if err := rows.Scan(&status); err != nil {
			return nil, err
		}
		items = append(items, status)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

