const tombstoneExpiredReaderComments = `-- name: TombstoneExpiredReaderComments :execrows

UPDATE reader_comments c
SET removed_at = now(),
    body = '',
    display_name = '',
    commenter_id = NULL,
    author_user_id = NULL,
    status = 'approved',
    trashed_from = NULL,
    held_reason = NULL,
    held_detail = NULL,
    notify_replies = false,
    network_hash = NULL,
    confirm_token_hash = NULL,
    edited_at = NULL,
    approved_at = coalesce(c.approved_at, now())
WHERE c.id IN (
  SELECT x.id FROM reader_comments x
  WHERE x.removed_at IS NULL
    AND (
      (x.status = 'unconfirmed' AND x.created_at < $1::timestamptz)
      OR (x.status = 'pending' AND x.created_at < $2::timestamptz)
      OR (x.status IN ('spam', 'trash') AND coalesce(x.moderated_at, x.created_at) < $3::timestamptz)
    )
    AND EXISTS (
      SELECT 1 FROM reader_comments r
      WHERE (r.root_id = x.id OR r.parent_id = x.id) AND r.status = 'approved'
    )
  FOR UPDATE OF x SKIP LOCKED
)
`

type TombstoneExpiredReaderCommentsParams struct {
	UnconfirmedBefore time.Time `json:"unconfirmed_before"`
	PendingBefore     time.Time `json:"pending_before"`
	RemovedBefore     time.Time `json:"removed_before"`
}

// ---------------------------------------------------------------------------------
// RunDiscussionMaintenance (api/discussion_maintenance.go, design 6.6). Each statement
// takes the rows it changes FOR UPDATE SKIP LOCKED, so replicas running it at the same
// time (and a moderator's transaction) never wait on each other or touch a row twice.
// The cut-off times come from Go, so the tests can pin them.
// Expired comments that approved replies still hang from become tombstones instead of
// being deleted: the root's ON DELETE CASCADE would take the replies (6.4).
func (q *Queries) TombstoneExpiredReaderComments(ctx context.Context, arg TombstoneExpiredReaderCommentsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, tombstoneExpiredReaderComments, arg.UnconfirmedBefore, arg.PendingBefore, arg.RemovedBefore)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

